import numpy as npclass NeuralNetwork:    # 3-layer network: INPUT -> HIDDEN -> OUTPUT    def __init__(self, input_size, hidden_size, output_size, learning_rate=0.3):        self.input_size = input_size        self.hidden_size = hidden_size        self.output_size = output_size        self.learning_rate = learning_rate                self.c = 1 / learning_rate        # Weights and biases        self.weights_input_hidden = np.random.uniform(-0.5, 0.5, (hidden_size, input_size))        self.bias_hidden = np.random.uniform(-0.5, 0.5, (hidden_size, 1))        self.weights_hidden_output = np.random.uniform(-0.5, 0.5, (output_size, hidden_size))        self.bias_output = np.random.uniform(-0.5, 0.5, (output_size, 1))    # Sigmoid activation function    def sigmoid(self, x):        z = np.clip(x, -700, 700)        return 1.0 / (1.0 + np.exp(-z))    # Derivative of sigmoid    def sigmoid_derivative(self, output):        return output * (1.0 - output)    # Forward propagation    def forward(self, inputs):        x = np.asarray(inputs).reshape(-1, 1)        if x.shape[0] != self.input_size:            raise ValueError(f"Expected {self.input_size} inputs, received {x.shape[0]}.")        hidden = self.sigmoid(self.weights_input_hidden @ x + self.bias_hidden)        output = self.sigmoid(self.weights_hidden_output @ hidden + self.bias_output)        return hidden, output    # Prediction: output neuron with largest activation    def predict(self, inputs):        _, outputs = self.forward(inputs)        return int(np.argmax(outputs))    # Train one mini-batch using backpropagation    def train(self, mini_batch, j):        batch_size = len(mini_batch)        grad_w_ih = np.zeros_like(self.weights_input_hidden)        grad_b_h = np.zeros_like(self.bias_hidden)        grad_w_ho = np.zeros_like(self.weights_hidden_output)        grad_b_o = np.zeros_like(self.bias_output)        batch_loss = 0.0        for inputs, targets in mini_batch:            x = np.asarray(inputs).reshape(-1, 1)            y = np.asarray(targets).reshape(-1, 1)            hidden, output = self.forward(x)            # Mean Squared Error, used here only to monitor training            batch_loss += np.mean((y - output) ** 2)            # Output error and gradient            output_error = y - output            output_gradient = output_error * self.sigmoid_derivative(output)            # Hidden error and gradient            hidden_error = self.weights_hidden_output.T @ output_gradient            hidden_gradient = hidden_error * self.sigmoid_derivative(hidden)            # Accumulate gradients            grad_b_o += output_gradient            grad_w_ho += output_gradient @ hidden.T            grad_b_h += hidden_gradient            grad_w_ih += hidden_gradient @ x.T        # Average gradient over the mini-batch        lr = 1/ (self.c * (j + 1) * batch_size)        self.weights_hidden_output += lr * grad_w_ho        self.bias_output += lr * grad_b_o        self.weights_input_hidden += lr * grad_w_ih        self.bias_hidden += lr * grad_b_h        return batch_loss / batch_size